#requires -Version 5.1
[CmdletBinding()]
param(
    [ValidateSet('Install','Repair','Verify','Preflight','Uninstall','BackendRecovery','SelfTest')]
    [string]$Action = 'Repair',

    [string]$InstallRoot = "$env:ProgramData\EInfra-OpenWebUI",
    [string]$RuntimeConfigPath,
    [string]$TokenFile,
    [switch]$PromptForCredential,
    [string]$Email,
    [string]$PasswordFile,
    [string]$CaCertificate,
    [switch]$InsecureTls,
    [double]$RequestTimeout = 15,
    [double]$StartupTimeout = 300,
    [double]$RouteTimeout = 180,
    [ValidateSet('Never','OnFailure','Always')]
    [string]$RestartPolicy = 'OnFailure',
    [ValidateSet('Skip','BestEffort','Required')]
    [string]$PublicVerification = 'BestEffort',
    [switch]$NoRollback,
    [switch]$KeepLegacyDisabled,
    [string]$BackupDir,
    [string]$ReportPath = '.\vut-ai-tutor-einfra-report.json',
    [string]$PythonPath,
    [switch]$KeepPayloadDirectory,
    [ValidateSet('Disabled','Auto','Required')]
    [string]$TutorStartupRecovery = 'Auto',
    [ValidateRange(3,120)]
    [int]$CrashGraceSeconds = 12,
    [ValidateRange(20,500)]
    [int]$DiagnosticTailLines = 120
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'
[Net.ServicePointManager]::SecurityProtocol = [Net.SecurityProtocolType]::Tls12
$AdapterVersion = '2.1.8'
$AdapterFix = 'backend-log-run-header-segmentation-v2+unified-pdf-delivery-r2'
$RuntimeVersion = '1.26.5'
$BackendTaskName = 'e-INFRA Open WebUI Backend'
$ProxyTaskName = 'e-INFRA Open WebUI HTTPS'
$DiagnosticsEnabled = $PSBoundParameters.ContainsKey('Debug') -and [bool]$PSBoundParameters['Debug']
$script:BackendRunStartPattern = '^---\s+.+?\s+start:\s+"?(?:[^"\r\n]*[\\/])?open-webui(?:\.exe)?"?\s+serve(?:\s|$)'

function Resolve-AbsolutePath {
    param([string]$Path, [switch]$MustExist)
    if ([string]::IsNullOrWhiteSpace($Path)) { return $null }
    $candidate = if ([IO.Path]::IsPathRooted($Path)) { $Path } else { Join-Path (Get-Location) $Path }
    $full = [IO.Path]::GetFullPath($candidate)
    if ($MustExist -and -not (Test-Path -LiteralPath $full -PathType Leaf)) {
        throw ('Soubor nebyl nalezen: {0}' -f $full)
    }
    return $full
}

function Get-ObjectPropertyValue {
    param(
        [Parameter(Mandatory=$true)]$Object,
        [Parameter(Mandatory=$true)][string[]]$Names,
        $DefaultValue = $null
    )
    foreach ($name in $Names) {
        foreach ($property in @($Object.PSObject.Properties)) {
            if ([string]::Equals([string]$property.Name, $name, [StringComparison]::OrdinalIgnoreCase)) {
                return $property.Value
            }
        }
    }
    return $DefaultValue
}

function Resolve-Python {
    param([string]$Requested)
    if (-not [string]::IsNullOrWhiteSpace($Requested)) {
        return (Resolve-Path -LiteralPath $Requested -ErrorAction Stop).Path
    }
    foreach ($candidate in @('py.exe','python.exe','python3.exe','python3','python')) {
        $command = Get-Command $candidate -ErrorAction SilentlyContinue
        if ($null -ne $command) { return $command.Source }
    }
    throw 'Python 3.11 nebo novejsi nebyl nalezen. Pouzijte -PythonPath.'
}

function Assert-WindowsAdministrator {
    if ($PSVersionTable.PSVersion.Major -ge 6 -and -not $IsWindows) {
        throw 'Tento adapter je urcen pouze pro Windows.'
    }
    $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
    $principal = New-Object -TypeName Security.Principal.WindowsPrincipal -ArgumentList $identity
    if (-not $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)) {
        throw 'Spustte Windows PowerShell jako spravce; sprava e-INFRA Scheduled Tasks vyzaduje administratorska opravneni.'
    }
}

function Test-IsLoopbackHost {
    param([Parameter(Mandatory=$true)][string]$HostName)
    $value = $HostName.Trim().Trim('[',']').ToLowerInvariant()
    if ($value -in @('localhost','127.0.0.1','::1')) { return $true }
    $address = $null
    if ([Net.IPAddress]::TryParse($value, [ref]$address)) { return [Net.IPAddress]::IsLoopback($address) }
    return $false
}

function Get-EInfraRuntimeContext {
    $root = [IO.Path]::GetFullPath($InstallRoot)
    $configPath = if ([string]::IsNullOrWhiteSpace($RuntimeConfigPath)) {
        Join-Path $root 'config\runtime.json'
    } else {
        Resolve-AbsolutePath -Path $RuntimeConfigPath -MustExist
    }
    if (-not (Test-Path -LiteralPath $configPath -PathType Leaf)) {
        throw ('Konfigurace instalace e-INFRA Open WebUI nebyla nalezena: {0}' -f $configPath)
    }
    $config = Get-Content -LiteralPath $configPath -Raw -Encoding UTF8 | ConvertFrom-Json
    $productId = [string](Get-ObjectPropertyValue -Object $config -Names @('ProductId','product_id') -DefaultValue '')
    if (-not [string]::IsNullOrWhiteSpace($productId) -and $productId -ne 'EInfra-OpenWebUI') {
        throw ('Runtime konfigurace patri produktu {0}, nikoli EInfra-OpenWebUI.' -f $productId)
    }
    $configuredRoot = [string](Get-ObjectPropertyValue -Object $config -Names @('InstallRoot','install_root') -DefaultValue $root)
    if (-not [string]::IsNullOrWhiteSpace($configuredRoot)) { $root = [IO.Path]::GetFullPath($configuredRoot) }
    $hostName = [string](Get-ObjectPropertyValue -Object $config -Names @('BackendHost','backend_host','host') -DefaultValue '127.0.0.1')
    if (-not (Test-IsLoopbackHost -HostName $hostName)) {
        throw ('EInfraWindows adapter povoluje pouze loopback backend; runtime.json uvadi {0}.' -f $hostName)
    }
    $portValue = Get-ObjectPropertyValue -Object $config -Names @('BackendPort','backend_port','port') -DefaultValue 18080
    $port = 0
    if (-not [int]::TryParse([string]$portValue, [ref]$port) -or $port -lt 1 -or $port -gt 65535) {
        throw ('Neplatny BackendPort v runtime.json: {0}' -f $portValue)
    }
    $publicUrl = [string](Get-ObjectPropertyValue -Object $config -Names @('PrimaryUrl','public_url','PublicUrl') -DefaultValue '')
    $runner = Join-Path $root 'config\Run-Component.ps1'
    $openWebUiExe = [string](Get-ObjectPropertyValue -Object $config -Names @('OpenWebUIExecutable','open_webui_executable') -DefaultValue (Join-Path $root 'venv\Scripts\open-webui.exe'))
    $caddyExe = [string](Get-ObjectPropertyValue -Object $config -Names @('CaddyExecutable','caddy_executable') -DefaultValue (Join-Path $root 'bin\caddy\caddy.exe'))
    $dataDirectory = [string](Get-ObjectPropertyValue -Object $config -Names @('DataDirectory','data_directory','DataDir') -DefaultValue (Join-Path $root 'data'))
    $logDirectory = [string](Get-ObjectPropertyValue -Object $config -Names @('LogDirectory','log_directory','LogDir') -DefaultValue (Join-Path $root 'logs'))
    if ([string]::IsNullOrWhiteSpace($dataDirectory)) { $dataDirectory = Join-Path $root 'data' }
    if ([string]::IsNullOrWhiteSpace($logDirectory)) { $logDirectory = Join-Path $root 'logs' }
    $dataDirectory = [IO.Path]::GetFullPath($dataDirectory)
    $logDirectory = [IO.Path]::GetFullPath($logDirectory)
    $venvRoot = [IO.Path]::GetFullPath((Join-Path $root 'venv'))
    foreach ($required in @($runner,$openWebUiExe,$caddyExe)) {
        if (-not (Test-Path -LiteralPath $required -PathType Leaf)) {
            throw ('Povinna soucast e-INFRA instalace nebyla nalezena: {0}' -f $required)
        }
    }
    return [pscustomobject][ordered]@{
        InstallRoot = $root
        RuntimeConfigPath = $configPath
        RuntimeConfig = $config
        BackendHost = $hostName
        BackendPort = $port
        InternalUrl = ('http://127.0.0.1:{0}' -f $port)
        PublicUrl = $publicUrl.TrimEnd('/')
        RunnerPath = $runner
        OpenWebUIExecutable = $openWebUiExe
        CaddyExecutable = $caddyExe
        DataDirectory = $dataDirectory
        DatabasePath = (Join-Path $dataDirectory 'webui.db')
        LogDirectory = $logDirectory
        BackendLogPath = (Join-Path $logDirectory 'open-webui.log')
        VenvRoot = $venvRoot
        BackendTaskName = $BackendTaskName
        ProxyTaskName = $ProxyTaskName
    }
}

function Test-TaskOwnership {
    param(
        [Parameter(Mandatory=$true)][string]$TaskName,
        [Parameter(Mandatory=$true)][string]$RunnerPath,
        [Parameter(Mandatory=$true)][ValidateSet('Backend','Caddy')][string]$Component,
        [switch]$AllowMissing
    )
    $task = Get-ScheduledTask -TaskName $TaskName -ErrorAction SilentlyContinue
    if ($null -eq $task) {
        if ($AllowMissing) { return $false }
        throw ('Planovana uloha nebyla nalezena: {0}' -f $TaskName)
    }
    $runnerNeedle = [IO.Path]::GetFullPath($RunnerPath).ToLowerInvariant()
    $componentNeedle = ('-component {0}' -f $Component).ToLowerInvariant()
    foreach ($taskAction in @($task.Actions)) {
        $description = (([string]$taskAction.Execute) + ' ' + ([string]$taskAction.Arguments) + ' ' + ([string]$taskAction.WorkingDirectory)).ToLowerInvariant()
        if ($description.Contains($runnerNeedle) -and $description.Contains($componentNeedle)) { return $true }
    }
    throw ('Planovana uloha {0} nepatri overene instalaci {1}.' -f $TaskName,$RunnerPath)
}

function Invoke-CapturedProcess {
    param(
        [Parameter(Mandatory=$true)][string]$FileName,
        [Parameter(Mandatory=$true)][string[]]$Arguments,
        [hashtable]$Environment = @{}
    )
    $psi = New-Object Diagnostics.ProcessStartInfo
    $psi.FileName = $FileName
    $psi.UseShellExecute = $false
    $psi.RedirectStandardOutput = $true
    $psi.RedirectStandardError = $true
    $psi.CreateNoWindow = $true
    $quoted = foreach ($argument in $Arguments) {
        $value = [string]$argument
        if ($value -notmatch '[\s"]') { $value }
        else { '"' + ($value -replace '(\\*)"','$1$1\"' -replace '(\\+)$','$1$1') + '"' }
    }
    $psi.Arguments = ($quoted -join ' ')
    foreach ($key in $Environment.Keys) {
        if ($null -eq $Environment[$key]) { $psi.EnvironmentVariables.Remove([string]$key) }
        else { $psi.EnvironmentVariables[[string]$key] = [string]$Environment[$key] }
    }
    $process = New-Object Diagnostics.Process
    $process.StartInfo = $psi
    if (-not $process.Start()) { throw ('Nelze spustit {0}.' -f $FileName) }
    $stdoutTask = $process.StandardOutput.ReadToEndAsync()
    $stderrTask = $process.StandardError.ReadToEndAsync()
    $process.WaitForExit()
    $stdout = $stdoutTask.Result
    $stderr = $stderrTask.Result
    if ($stdout) { [Console]::Out.Write($stdout) }
    if ($stderr) { [Console]::Error.Write($stderr) }
    $exitCode = [int]$process.ExitCode
    $process.Dispose()
    return [pscustomobject]@{ ExitCode=$exitCode; StdOut=$stdout; StdErr=$stderr }
}

function Test-TcpPort {
    param(
        [Parameter(Mandatory=$true)][string]$HostName,
        [Parameter(Mandatory=$true)][int]$Port,
        [ValidateRange(100,10000)][int]$TimeoutMilliseconds = 750
    )
    $client = New-Object Net.Sockets.TcpClient
    try {
        $async = $client.BeginConnect($HostName,$Port,$null,$null)
        if (-not $async.AsyncWaitHandle.WaitOne($TimeoutMilliseconds,$false)) { return $false }
        $client.EndConnect($async)
        return $true
    }
    catch { return $false }
    finally { $client.Dispose() }
}

function Test-BackendReady {
    param([Parameter(Mandatory=$true)][string]$BaseUrl)
    try {
        $response = Invoke-RestMethod -UseBasicParsing -Uri ($BaseUrl.TrimEnd('/') + '/api/version') -Method Get -TimeoutSec 5
        return $null -ne $response -and $response.PSObject.Properties.Name -contains 'version' -and -not [string]::IsNullOrWhiteSpace([string]$response.version)
    }
    catch { return $false }
}

function Get-ProtectedProcessIds {
    $processes = @(Get-CimInstance -ClassName Win32_Process -ErrorAction Stop)
    $parents = @{}
    foreach ($process in $processes) { $parents[[int]$process.ProcessId] = [int]$process.ParentProcessId }
    $protected = [Collections.Generic.HashSet[int]]::new()
    $current = [int]$PID
    while ($current -gt 0 -and $protected.Add($current)) {
        if (-not $parents.ContainsKey($current)) { break }
        $next = [int]$parents[$current]
        if ($next -le 0 -or $next -eq $current) { break }
        $current = $next
    }
    return [int[]]@($protected)
}

function Test-BackendProcessOwned {
    param(
        [Parameter(Mandatory=$true)]$Process,
        [Parameter(Mandatory=$true)]$Context,
        [int[]]$ProtectedProcessIds = @()
    )
    $pidValue = [int]$Process.ProcessId
    if ($ProtectedProcessIds -contains $pidValue) { return $false }
    $commandLine = ([string]$Process.CommandLine).ToLowerInvariant()
    $executablePath = ([string]$Process.ExecutablePath).Trim()
    $executableLower = ''
    if (-not [string]::IsNullOrWhiteSpace($executablePath)) {
        try { $executableLower = [IO.Path]::GetFullPath($executablePath).ToLowerInvariant() }
        catch { $executableLower = $executablePath.ToLowerInvariant() }
    }
    $caddyLower = [IO.Path]::GetFullPath([string]$Context.CaddyExecutable).ToLowerInvariant()
    if ($executableLower -eq $caddyLower) { return $false }
    $venvPrefix = [IO.Path]::GetFullPath([string]$Context.VenvRoot).TrimEnd('\\').ToLowerInvariant() + '\\'
    $runnerLower = [IO.Path]::GetFullPath([string]$Context.RunnerPath).ToLowerInvariant()
    $openWebUiLower = [IO.Path]::GetFullPath([string]$Context.OpenWebUIExecutable).ToLowerInvariant()
    $runnerBackend = $commandLine.Contains($runnerLower) -and $commandLine -match '(?i)-component\s+backend(?:\s|$)'
    $openWebUiCommand = $commandLine.Contains($openWebUiLower) -or $commandLine -match '(?i)(?:^|\s)(?:open-webui(?:\.exe)?|open_webui)(?:\s|$)' -or $commandLine -match '(?i)-m\s+(?:uv\s+run\s+)?open[-_]webui\s+serve'
    if ($runnerBackend -or $executableLower -eq $openWebUiLower) { return $true }
    if ($executableLower.StartsWith($venvPrefix) -and $openWebUiCommand) { return $true }
    $pythonRoot = [IO.Path]::GetFullPath((Join-Path ([string]$Context.InstallRoot) 'python')).TrimEnd('\\').ToLowerInvariant() + '\\'
    if ($executableLower.StartsWith($pythonRoot) -and $openWebUiCommand) { return $true }
    return $false
}

function Get-EInfraBackendProcesses {
    param([Parameter(Mandatory=$true)]$Context)
    $all = @(Get-CimInstance -ClassName Win32_Process -ErrorAction Stop)
    $protected = @(Get-ProtectedProcessIds)
    $selected = [Collections.Generic.HashSet[int]]::new()
    foreach ($process in $all) {
        if (Test-BackendProcessOwned -Process $process -Context $Context -ProtectedProcessIds $protected) {
            [void]$selected.Add([int]$process.ProcessId)
        }
    }
    $changed = $true
    while ($changed) {
        $changed = $false
        foreach ($process in $all) {
            $pidValue = [int]$process.ProcessId
            if ($protected -contains $pidValue -or $selected.Contains($pidValue)) { continue }
            if ($selected.Contains([int]$process.ParentProcessId)) {
                [void]$selected.Add($pidValue)
                $changed = $true
            }
        }
    }
    return @($all | Where-Object { $selected.Contains([int]$_.ProcessId) })
}

function Stop-EInfraBackendProcesses {
    param([Parameter(Mandatory=$true)]$Context, [switch]$RequireStopped)
    $processes = @(Get-EInfraBackendProcesses -Context $Context)
    foreach ($process in $processes | Sort-Object ProcessId -Descending) {
        Stop-Process -Id ([int]$process.ProcessId) -Force -ErrorAction SilentlyContinue
    }
    if (-not $RequireStopped) { return }
    $deadline = [DateTime]::UtcNow.AddSeconds(15)
    $remaining = @()
    do {
        Start-Sleep -Milliseconds 500
        $remaining = @(Get-EInfraBackendProcesses -Context $Context)
    } while ($remaining.Count -gt 0 -and [DateTime]::UtcNow -lt $deadline)
    if ($remaining.Count -gt 0) {
        $description = @($remaining | ForEach-Object { 'PID {0} ({1})' -f $_.ProcessId,$_.Name }) -join ', '
        throw ('Spravovane procesy Open WebUI backendu se nepodarilo ukoncit: {0}' -f $description)
    }
}

function New-PortOwnerRecord {
    param(
        [Parameter(Mandatory=$true)][int]$ProcessId,
        [string]$LocalAddress = ''
    )
    $process = Get-CimInstance -ClassName Win32_Process -Filter ('ProcessId={0}' -f $ProcessId) -ErrorAction SilentlyContinue
    return [pscustomobject][ordered]@{
        ProcessId = $ProcessId
        LocalAddress = $LocalAddress
        Name = if ($null -ne $process) { [string]$process.Name } else { '' }
        ExecutablePath = if ($null -ne $process) { [string]$process.ExecutablePath } else { '' }
        CommandLine = if ($null -ne $process) { [string]$process.CommandLine } else { '' }
    }
}

function Get-PortOwners {
    param([Parameter(Mandatory=$true)][int]$Port)
    $records = [Collections.Generic.List[object]]::new()
    $seen = [Collections.Generic.HashSet[int]]::new()
    try {
        foreach ($connection in @(Get-NetTCPConnection -State Listen -LocalPort $Port -ErrorAction Stop)) {
            $owner = [int]$connection.OwningProcess
            if ($seen.Add($owner)) {
                [void]$records.Add((New-PortOwnerRecord -ProcessId $owner -LocalAddress ([string]$connection.LocalAddress)))
            }
        }
    }
    catch {
        # Windows Server Core or older hosts can lack Get-NetTCPConnection.  Use
        # netstat only as a read-only diagnostic fallback and still resolve the
        # PID through Win32_Process.
        $netstat = Join-Path $env:SystemRoot 'System32\netstat.exe'
        if (Test-Path -LiteralPath $netstat -PathType Leaf) {
            try {
                foreach ($line in @(& $netstat -ano -p tcp 2>$null)) {
                    $match = [regex]::Match([string]$line, ('^\s*TCP\s+(?<local>\S+:{0})\s+\S+\s+LISTENING\s+(?<pid>\d+)\s*$' -f $Port), [Text.RegularExpressions.RegexOptions]::IgnoreCase)
                    if (-not $match.Success) { continue }
                    $owner = [int]$match.Groups['pid'].Value
                    if ($seen.Add($owner)) {
                        [void]$records.Add((New-PortOwnerRecord -ProcessId $owner -LocalAddress $match.Groups['local'].Value))
                    }
                }
            }
            catch { }
        }
    }
    return @($records.ToArray())
}

function Wait-BackendPortReleased {
    param([Parameter(Mandatory=$true)]$Context, [int]$TimeoutSeconds = 20)
    $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    while ([DateTime]::UtcNow -lt $deadline) {
        if (-not (Test-TcpPort -HostName '127.0.0.1' -Port ([int]$Context.BackendPort) -TimeoutMilliseconds 300)) { return }
        Start-Sleep -Milliseconds 500
    }
    $owners = @(Get-PortOwners -Port ([int]$Context.BackendPort))
    $description = if ($owners.Count -gt 0) {
        @($owners | ForEach-Object { 'PID {0} ({1}) {2}' -f $_.ProcessId,$_.Name,$_.ExecutablePath }) -join '; '
    } else { 'vlastnika listeneru se nepodarilo zjistit' }
    throw ('Backendovy port {0} zustal po zastaveni obsazen: {1}' -f $Context.BackendPort,$description)
}

function ConvertTo-TaskResultHex {
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    $signed = [int64]$Value
    $unsigned = $signed % 4294967296
    if ($unsigned -lt 0) { $unsigned += 4294967296 }
    return ('0x{0:X8}' -f [uint64]$unsigned)
}

function Get-TaskResultMeaning {
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    $signed = [int64]$Value
    $unsigned = $signed % 4294967296
    if ($unsigned -lt 0) { $unsigned += 4294967296 }
    switch ([uint64]$unsigned) {
        0       { return 'success' }
        267008  { return 'task-ready' }
        267009  { return 'task-running' }
        267010  { return 'task-disabled' }
        267011  { return 'task-not-yet-run' }
        267012  { return 'no-more-runs' }
        267013  { return 'task-not-scheduled' }
        267014  { return 'task-terminated' }
        default { return '' }
    }
}

function ConvertTo-NullableTaskResult {
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return $null }
    $text = [string]$Value
    if ([string]::IsNullOrWhiteSpace($text)) { return $null }
    try { return [int64]$Value }
    catch { return $null }
}

function ConvertTo-TaskDateTimeText {
    param([AllowNull()]$Value)
    if ($null -eq $Value) { return '' }
    try {
        if ($Value -is [DateTimeOffset]) {
            $dateTimeOffset = [DateTimeOffset]$Value
            if ($dateTimeOffset -eq [DateTimeOffset]::MinValue) { return '' }
            return $dateTimeOffset.ToString('o',[Globalization.CultureInfo]::InvariantCulture)
        }
        $dateTime = [DateTime]$Value
        if ($dateTime -eq [DateTime]::MinValue) { return '' }
        return $dateTime.ToString('o',[Globalization.CultureInfo]::InvariantCulture)
    }
    catch {
        $text = [string]$Value
        if ([string]::IsNullOrWhiteSpace($text)) { return '' }
        return $text
    }
}

function New-TaskDiagnosticRecord {
    param(
        [Parameter(Mandatory=$true)][string]$TaskName,
        [AllowNull()]$Task,
        [AllowNull()]$Info,
        [string]$TaskQueryError = '',
        [string]$TaskInfoQueryError = ''
    )

    $state = 'Missing'
    $actionValues = @()
    if ($null -ne $Task) {
        $stateValue = Get-ObjectPropertyValue -Object $Task -Names @('State') -DefaultValue 'Unknown'
        $state = [string]$stateValue
        if ([string]::IsNullOrWhiteSpace($state)) { $state = 'Unknown' }
        $actionValues = @(Get-ObjectPropertyValue -Object $Task -Names @('Actions') -DefaultValue @())
    }
    elseif (-not [string]::IsNullOrWhiteSpace($TaskQueryError)) {
        $state = 'Unavailable'
    }

    $lastResultRaw = $null
    $lastRunRaw = $null
    $nextRunRaw = $null
    $missedRunsRaw = $null
    if ($null -ne $Info) {
        $lastResultRaw = Get-ObjectPropertyValue -Object $Info -Names @('LastTaskResult') -DefaultValue $null
        $lastRunRaw = Get-ObjectPropertyValue -Object $Info -Names @('LastRunTime') -DefaultValue $null
        $nextRunRaw = Get-ObjectPropertyValue -Object $Info -Names @('NextRunTime') -DefaultValue $null
        $missedRunsRaw = Get-ObjectPropertyValue -Object $Info -Names @('NumberOfMissedRuns') -DefaultValue $null
    }
    $lastResult = ConvertTo-NullableTaskResult -Value $lastResultRaw
    $missedRuns = 0
    if ($null -ne $missedRunsRaw -and -not [string]::IsNullOrWhiteSpace([string]$missedRunsRaw)) {
        try { $missedRuns = [int]$missedRunsRaw }
        catch { $missedRuns = 0 }
    }

    $actions = [Collections.Generic.List[object]]::new()
    foreach ($action in @($actionValues)) {
        if ($null -eq $action) { continue }
        [void]$actions.Add([pscustomobject][ordered]@{
            Execute = [string](Get-ObjectPropertyValue -Object $action -Names @('Execute') -DefaultValue '')
            Arguments = [string](Get-ObjectPropertyValue -Object $action -Names @('Arguments') -DefaultValue '')
            WorkingDirectory = [string](Get-ObjectPropertyValue -Object $action -Names @('WorkingDirectory') -DefaultValue '')
        })
    }

    return [pscustomobject][ordered]@{
        TaskName = $TaskName
        TaskExists = $null -ne $Task
        TaskInfoAvailable = $null -ne $Info
        State = $state
        LastTaskResult = $lastResult
        LastTaskResultHex = ConvertTo-TaskResultHex -Value $lastResult
        LastTaskResultMeaning = Get-TaskResultMeaning -Value $lastResult
        LastRunTime = ConvertTo-TaskDateTimeText -Value $lastRunRaw
        NextRunTime = ConvertTo-TaskDateTimeText -Value $nextRunRaw
        NumberOfMissedRuns = $missedRuns
        TaskQueryError = $TaskQueryError
        TaskInfoQueryError = $TaskInfoQueryError
        Actions = @($actions.ToArray())
    }
}

function Get-TaskDiagnostic {
    param([Parameter(Mandatory=$true)][string]$TaskName)
    $task = $null
    $info = $null
    $taskQueryError = ''
    $taskInfoQueryError = ''
    try { $task = Get-ScheduledTask -TaskName $TaskName -ErrorAction Stop }
    catch { $taskQueryError = $_.Exception.Message }
    try { $info = Get-ScheduledTaskInfo -TaskName $TaskName -ErrorAction Stop }
    catch { $taskInfoQueryError = $_.Exception.Message }
    return New-TaskDiagnosticRecord -TaskName $TaskName -Task $task -Info $info -TaskQueryError $taskQueryError -TaskInfoQueryError $taskInfoQueryError
}

function Wait-EInfraBackendTaskQuiescent {
    param(
        [Parameter(Mandatory=$true)]$Context,
        [ValidateRange(3,120)][int]$TimeoutSeconds = 30
    )
    $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    $diagnostic = $null
    do {
        $diagnostic = Get-TaskDiagnostic -TaskName ([string]$Context.BackendTaskName)
        if ([string]$diagnostic.State -notin @('Running','Queued')) { return $diagnostic }
        Start-Sleep -Milliseconds 500
    } while ([DateTime]::UtcNow -lt $deadline)
    $path = Save-BackendFailureDiagnostics -Context $Context -Reason ('Planovana uloha nepresla do klidoveho stavu do {0} s.' -f $TimeoutSeconds)
    throw ('Planovana uloha {0} zustala ve stavu {1}; diagnostika: {2}' -f $Context.BackendTaskName,$diagnostic.State,$path)
}

function Test-BackendRunStartLine {
    param([AllowNull()][string]$Line)
    if ([string]::IsNullOrWhiteSpace($Line)) { return $false }
    return [bool]($Line -match $script:BackendRunStartPattern)
}

function Select-LatestBackendRunLines {
    param([string[]]$Lines, [int]$MaximumLines = 120)
    if ($null -eq $Lines -or $Lines.Count -eq 0) { return @() }
    $startIndex = -1
    for ($index = 0; $index -lt $Lines.Count; $index++) {
        if (Test-BackendRunStartLine -Line ([string]$Lines[$index])) { $startIndex = $index }
    }
    $selected = if ($startIndex -ge 0) { @($Lines[$startIndex..($Lines.Count - 1)]) } else { @($Lines) }
    if ($selected.Count -gt $MaximumLines) {
        if ($startIndex -ge 0 -and $MaximumLines -gt 1) {
            return @($selected[0]) + @($selected[($selected.Count - ($MaximumLines - 1))..($selected.Count - 1)])
        }
        return @($selected[($selected.Count - $MaximumLines)..($selected.Count - 1)])
    }
    return $selected
}

function Get-LatestBackendLogExcerpt {
    param([Parameter(Mandatory=$true)]$Context, [int]$MaximumLines = 120)
    $path = [string]$Context.BackendLogPath
    if (-not (Test-Path -LiteralPath $path -PathType Leaf)) { return @() }
    $tailCount = [Math]::Max($MaximumLines * 6,400)
    $lines = @(Get-Content -LiteralPath $path -Tail $tailCount -ErrorAction SilentlyContinue)
    return @(Select-LatestBackendRunLines -Lines $lines -MaximumLines $MaximumLines)
}

function Test-LatestLogIndicatesTutorStartupFailure {
    param([string[]]$Lines)
    $text = (@($Lines) -join "`n")
    if ([string]::IsNullOrWhiteSpace($text)) { return $false }
    $hasTutor = $text -match '(?i)(study_tutor_|vut_ai_tutor_|function_study_tutor|VUT AI Tutor|STUDY_TUTOR)'
    $hasFailure = $text -match '(?i)(traceback|runtimeerror|importerror|exception|\berror\b|failed|failure)'
    return $hasTutor -and $hasFailure
}

function Write-JsonNoBom {
    param([Parameter(Mandatory=$true)][string]$Path, [Parameter(Mandatory=$true)]$Value)
    $directory = Split-Path -Parent $Path
    if (-not [string]::IsNullOrWhiteSpace($directory)) { [IO.Directory]::CreateDirectory($directory) | Out-Null }
    $json = $Value | ConvertTo-Json -Depth 12
    [IO.File]::WriteAllText($Path,$json + "`r`n",(New-Object Text.UTF8Encoding($false)))
}

function Save-BackendFailureDiagnostics {
    param(
        [Parameter(Mandatory=$true)]$Context,
        [Parameter(Mandatory=$true)][string]$Reason,
        [DateTime]$StartRequestedUtc = [DateTime]::MinValue
    )
    $task = Get-TaskDiagnostic -TaskName ([string]$Context.BackendTaskName)
    $processes = @()
    try {
        $processes = @(Get-EInfraBackendProcesses -Context $Context | ForEach-Object {
            [pscustomobject][ordered]@{ ProcessId=[int]$_.ProcessId; ParentProcessId=[int]$_.ParentProcessId; Name=[string]$_.Name; ExecutablePath=[string]$_.ExecutablePath; CommandLine=[string]$_.CommandLine }
        })
    } catch { }
    $logLines = @(Get-LatestBackendLogExcerpt -Context $Context -MaximumLines $DiagnosticTailLines)
    $logLastWriteUtc = ''
    $logAdvancedAfterStart = $false
    if (Test-Path -LiteralPath $Context.BackendLogPath -PathType Leaf) {
        try {
            $lastWrite = (Get-Item -LiteralPath $Context.BackendLogPath -ErrorAction Stop).LastWriteTimeUtc
            $logLastWriteUtc = $lastWrite.ToString('o')
            if ($StartRequestedUtc -ne [DateTime]::MinValue) { $logAdvancedAfterStart = $lastWrite -ge $StartRequestedUtc.AddSeconds(-2) }
        }
        catch { }
    }
    $diagnostic = [pscustomobject][ordered]@{
        TimestampUtc = [DateTimeOffset]::UtcNow.ToString('o')
        Reason = $Reason
        StartRequestedUtc = if ($StartRequestedUtc -ne [DateTime]::MinValue) { $StartRequestedUtc.ToString('o') } else { '' }
        InternalUrl = [string]$Context.InternalUrl
        BackendPortOpen = [bool](Test-TcpPort -HostName '127.0.0.1' -Port ([int]$Context.BackendPort) -TimeoutMilliseconds 500)
        RuntimeConfigPath = [string]$Context.RuntimeConfigPath
        RunnerPath = [string]$Context.RunnerPath
        RunnerExists = [bool](Test-Path -LiteralPath $Context.RunnerPath -PathType Leaf)
        OpenWebUIExecutable = [string]$Context.OpenWebUIExecutable
        OpenWebUIExecutableExists = [bool](Test-Path -LiteralPath $Context.OpenWebUIExecutable -PathType Leaf)
        BackendLogPath = [string]$Context.BackendLogPath
        BackendLogLastWriteUtc = $logLastWriteUtc
        BackendLogAdvancedAfterStart = [bool]$logAdvancedAfterStart
        Task = $task
        PortOwners = @(Get-PortOwners -Port ([int]$Context.BackendPort))
        ManagedBackendProcesses = $processes
        LatestBackendRun = $logLines
        TutorFailureDetected = [bool](Test-LatestLogIndicatesTutorStartupFailure -Lines $logLines)
    }
    $path = if (-not [string]::IsNullOrWhiteSpace([string]$script:ResolvedReportPath)) {
        [string]$script:ResolvedReportPath + '.backend-startup.json'
    } else {
        Join-Path ([string]$Context.LogDirectory) 'vut-ai-tutor-backend-startup-diagnostics.json'
    }
    Write-JsonNoBom -Path $path -Value $diagnostic
    Write-Warning ('Backendova diagnostika byla ulozena do {0}' -f $path)
    if ($logLines.Count -gt 0) {
        Write-Host ('--- Posledni beh {0} ---' -f $Context.BackendLogPath) -ForegroundColor Yellow
        foreach ($line in @($logLines | Select-Object -Last 50)) { Write-Host $line }
        Write-Host '--- konec diagnostiky ---' -ForegroundColor Yellow
    }
    return $path
}

function Stop-EInfraBackendCompletely {
    param([Parameter(Mandatory=$true)]$Context)
    [void](Test-TaskOwnership -TaskName $Context.BackendTaskName -RunnerPath $Context.RunnerPath -Component Backend)
    Stop-ScheduledTask -TaskName $Context.BackendTaskName -ErrorAction SilentlyContinue
    Start-Sleep -Seconds 2
    Stop-EInfraBackendProcesses -Context $Context -RequireStopped
    Wait-BackendPortReleased -Context $Context -TimeoutSeconds 20
    [void](Wait-EInfraBackendTaskQuiescent -Context $Context -TimeoutSeconds 30)
}

function Wait-BackendReady {
    param(
        [Parameter(Mandatory=$true)]$Context,
        [int]$TimeoutSeconds = 300,
        [switch]$MonitorTaskExit,
        [DateTime]$StartRequestedUtc = ([DateTime]::UtcNow)
    )
    $deadline = [DateTime]::UtcNow.AddSeconds($TimeoutSeconds)
    $observedRunning = $false
    $lastState = ''
    $lastResult = $null
    $lastResultHex = ''
    while ([DateTime]::UtcNow -lt $deadline) {
        if (Test-BackendReady -BaseUrl $Context.InternalUrl) { return }
        $taskDiagnostic = Get-TaskDiagnostic -TaskName ([string]$Context.BackendTaskName)
        $lastState = [string]$taskDiagnostic.State
        $lastResult = $taskDiagnostic.LastTaskResult
        $lastResultHex = [string]$taskDiagnostic.LastTaskResultHex
        if ($lastState -eq 'Running') { $observedRunning = $true }
        $elapsed = ([DateTime]::UtcNow - $StartRequestedUtc).TotalSeconds
        $taskStateCanProveExit = $lastState -notin @('', 'Missing', 'Unavailable', 'Unknown')
        if ($MonitorTaskExit -and $taskStateCanProveExit -and $elapsed -ge $CrashGraceSeconds -and $lastState -notin @('Running','Queued')) {
            $portOpen = Test-TcpPort -HostName '127.0.0.1' -Port ([int]$Context.BackendPort) -TimeoutMilliseconds 300
            $lastRunAdvanced = $false
            if (-not [string]::IsNullOrWhiteSpace([string]$taskDiagnostic.LastRunTime)) {
                $lastRun = [DateTime]::MinValue
                if ([DateTime]::TryParse([string]$taskDiagnostic.LastRunTime,[ref]$lastRun)) {
                    $lastRunAdvanced = $lastRun.ToUniversalTime() -ge $StartRequestedUtc.AddSeconds(-3)
                }
            }
            if (-not $portOpen -and ($observedRunning -or $lastRunAdvanced -or $elapsed -ge 30)) {
                $reason = 'Planovana uloha backendu skoncila pred readiness; state={0}, LastTaskResult={1} ({2})' -f $lastState,$lastResult,$lastResultHex
                $path = Save-BackendFailureDiagnostics -Context $Context -Reason $reason -StartRequestedUtc $StartRequestedUtc
                throw ('Open WebUI backend skoncil pred dokoncenim startu. Stav ulohy: {0}; LastTaskResult: {1} ({2}); diagnostika: {3}' -f $lastState,$lastResult,$lastResultHex,$path)
            }
        }
        Start-Sleep -Seconds 2
    }
    $reason = 'Backend nebyl pripraven do {0} s; state={1}, LastTaskResult={2} ({3})' -f $TimeoutSeconds,$lastState,$lastResult,$lastResultHex
    $path = Save-BackendFailureDiagnostics -Context $Context -Reason $reason -StartRequestedUtc $StartRequestedUtc
    throw ('Open WebUI backend {0} nebyl pripraven do {1} s; stav ulohy: {2}; LastTaskResult: {3} ({4}); diagnostika: {5}' -f $Context.InternalUrl,$TimeoutSeconds,$lastState,$lastResult,$lastResultHex,$path)
}

function Start-EInfraBackendTask {
    param([Parameter(Mandatory=$true)]$Context)
    [void](Test-TaskOwnership -TaskName $Context.BackendTaskName -RunnerPath $Context.RunnerPath -Component Backend)
    $before = Wait-EInfraBackendTaskQuiescent -Context $Context -TimeoutSeconds 30
    if ([string]$before.State -eq 'Disabled') {
        throw ('Planovana uloha {0} je zakazana; aktivujte ji nebo opravte instalaci Open WebUI pomoci jejiho puvodniho instalatoru --resume.' -f $Context.BackendTaskName)
    }
    $requested = [DateTime]::UtcNow
    Start-ScheduledTask -TaskName $Context.BackendTaskName -ErrorAction Stop
    Wait-BackendReady -Context $Context -TimeoutSeconds ([int]$StartupTimeout) -MonitorTaskExit -StartRequestedUtc $requested
}

function Restart-EInfraBackend {
    param([Parameter(Mandatory=$true)]$Context)
    Write-Host ('[INFO] Restartuji pouze planovanou ulohu {0} a jeji overene backendove procesy.' -f $Context.BackendTaskName)
    Stop-EInfraBackendCompletely -Context $Context
    Start-EInfraBackendTask -Context $Context
}

function Invoke-OfflineTutorFunctionDeactivation {
    param(
        [Parameter(Mandatory=$true)]$Context,
        [Parameter(Mandatory=$true)][string]$Python,
        [string]$RecoveryRoot
    )
    if (-not (Test-Path -LiteralPath $Context.DatabasePath -PathType Leaf)) {
        throw ('Databaze Open WebUI nebyla nalezena: {0}' -f $Context.DatabasePath)
    }
    if ([string]::IsNullOrWhiteSpace($RecoveryRoot)) {
        $RecoveryRoot = Join-Path ([string]$Context.InstallRoot) 'backups\vut-tutor-startup-recovery'
    }
    [IO.Directory]::CreateDirectory($RecoveryRoot) | Out-Null
    $helper = Join-Path ([IO.Path]::GetTempPath()) ('vut-tutor-offline-disable-' + [Guid]::NewGuid().ToString('N') + '.py')
    $resultPath = Join-Path $RecoveryRoot ('vut-tutor-offline-disable-' + [DateTime]::UtcNow.ToString('yyyyMMdd-HHmmss-fff') + '.json')
    $pythonSource = @'
import json, pathlib, sqlite3, sys, time

db_path = pathlib.Path(sys.argv[1]).resolve()
backup_dir = pathlib.Path(sys.argv[2]).resolve()
result_path = pathlib.Path(sys.argv[3]).resolve()
ids = (
    "study_tutor_gateway_bootstrap",
    "study_tutor_pipe",
    "study_tutor_bootstrap",
    "study_tutor_canvas_bootstrap",
    "vut_ai_tutor_bootstrap",
    "vut_ai_tutor_pipe",
    "study_tutor_pipe_managed",
)
backup_dir.mkdir(parents=True, exist_ok=True)
backup_path = backup_dir / ("webui-before-vut-tutor-disable-" + time.strftime("%Y%m%d-%H%M%S") + "-" + str(time.time_ns()) + ".db")

def quote_identifier(value):
    return '"' + value.replace('"', '""') + '"'

source = sqlite3.connect(str(db_path), timeout=30)
try:
    check = [row[0] for row in source.execute("PRAGMA quick_check")]
    if check != ["ok"]:
        raise RuntimeError("SQLite quick_check failed: " + repr(check))
    tables = [row[0] for row in source.execute("SELECT name FROM sqlite_master WHERE type='table'")]
    candidates = []
    for table in tables:
        columns = [row[1].lower() for row in source.execute("PRAGMA table_info(" + quote_identifier(table) + ")")]
        if "id" in columns and "is_active" in columns and table.lower() in {"function", "functions"}:
            candidates.append(table)
    if len(candidates) != 1:
        raise RuntimeError("Expected exactly one Function table with id/is_active; found: " + repr(candidates))
    table = candidates[0]
    quoted = quote_identifier(table)
    placeholders = ",".join("?" for _ in ids)
    before = [dict(id=row[0], is_active=bool(row[1])) for row in source.execute(
        "SELECT id,is_active FROM " + quoted + " WHERE id IN (" + placeholders + ") ORDER BY id", ids
    )]
    destination = sqlite3.connect(str(backup_path))
    try:
        source.backup(destination)
    finally:
        destination.close()
    source.execute("BEGIN IMMEDIATE")
    cursor = source.execute(
        "UPDATE " + quoted + " SET is_active=0 WHERE id IN (" + placeholders + ") AND is_active<>0", ids
    )
    source.commit()
    after = [dict(id=row[0], is_active=bool(row[1])) for row in source.execute(
        "SELECT id,is_active FROM " + quoted + " WHERE id IN (" + placeholders + ") ORDER BY id", ids
    )]
    check_after = [row[0] for row in source.execute("PRAGMA quick_check")]
    if check_after != ["ok"]:
        raise RuntimeError("SQLite quick_check after update failed: " + repr(check_after))
    result = {
        "ok": True,
        "database": str(db_path),
        "backup": str(backup_path),
        "table": table,
        "updated_count": int(cursor.rowcount if cursor.rowcount is not None else 0),
        "before": before,
        "after": after,
    }
finally:
    source.close()
result_path.write_text(json.dumps(result, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
print(json.dumps(result, ensure_ascii=False))
'@
    [IO.File]::WriteAllText($helper,$pythonSource,(New-Object Text.UTF8Encoding($false)))
    try {
        $result = Invoke-CapturedProcess -FileName $Python -Arguments @($helper,[string]$Context.DatabasePath,$RecoveryRoot,$resultPath)
        if ($result.ExitCode -ne 0) { throw ('Offline deaktivace Tutor Functions skoncila kodem {0}.' -f $result.ExitCode) }
        if (-not (Test-Path -LiteralPath $resultPath -PathType Leaf)) { throw 'Offline deaktivace nevytvorila auditni report.' }
        $audit = Get-Content -LiteralPath $resultPath -Raw -Encoding UTF8 | ConvertFrom-Json
        Write-Warning ('Tutor Functions byly kvuli obnoveni startupu offline deaktivovany. Zaloha databaze: {0}' -f $audit.backup)
        return $audit
    }
    finally { Remove-Item -LiteralPath $helper -Force -ErrorAction SilentlyContinue }
}

function Invoke-AdapterSelfTest {
    param([Parameter(Mandatory=$true)][string]$Python)
    $context = [pscustomobject]@{
        InstallRoot='C:\ProgramData\EInfra-OpenWebUI'
        VenvRoot='C:\ProgramData\EInfra-OpenWebUI\venv'
        RunnerPath='C:\ProgramData\EInfra-OpenWebUI\config\Run-Component.ps1'
        OpenWebUIExecutable='C:\ProgramData\EInfra-OpenWebUI\venv\Scripts\open-webui.exe'
        CaddyExecutable='C:\ProgramData\EInfra-OpenWebUI\bin\caddy\caddy.exe'
    }
    $protected = @(80,90,100)
    $cases = @(
        @{ Expected=$false; Process=[pscustomobject]@{ProcessId=100;ParentProcessId=90;ExecutablePath='C:\Python314\python.exe';CommandLine='python manager.py --install-root C:\ProgramData\EInfra-OpenWebUI'} },
        @{ Expected=$true; Process=[pscustomobject]@{ProcessId=200;ParentProcessId=1;ExecutablePath='C:\ProgramData\EInfra-OpenWebUI\venv\Scripts\open-webui.exe';CommandLine='open-webui.exe serve --port 18080'} },
        @{ Expected=$true; Process=[pscustomobject]@{ProcessId=201;ParentProcessId=1;ExecutablePath='C:\Windows\System32\WindowsPowerShell\v1.0\powershell.exe';CommandLine='powershell.exe -File C:\ProgramData\EInfra-OpenWebUI\config\Run-Component.ps1 -Component Backend'} },
        @{ Expected=$false; Process=[pscustomobject]@{ProcessId=300;ParentProcessId=1;ExecutablePath='C:\ProgramData\EInfra-OpenWebUI\bin\caddy\caddy.exe';CommandLine='caddy.exe run'} }
    )
    foreach ($case in $cases) {
        $actual = Test-BackendProcessOwned -Process $case.Process -Context $context -ProtectedProcessIds $protected
        if ([bool]$actual -ne [bool]$case.Expected) { throw ('Procesovy self-test selhal pro PID {0}.' -f $case.Process.ProcessId) }
    }
    if ((ConvertTo-TaskResultHex -Value -1) -ne '0xFFFFFFFF' -or (ConvertTo-TaskResultHex -Value 1) -ne '0x00000001') {
        throw 'Task result hexadecimal conversion self-test selhal.'
    }
    $syntheticTask = [pscustomobject]@{ State='Ready'; Actions=@() }
    $syntheticInfo = [pscustomobject]@{ LastTaskResult=$null; LastRunTime=$null; NextRunTime=$null; NumberOfMissedRuns=$null }
    $syntheticDiagnostic = New-TaskDiagnosticRecord -TaskName 'Synthetic null TaskInfo' -Task $syntheticTask -Info $syntheticInfo
    if ($syntheticDiagnostic.State -ne 'Ready' -or
        $null -ne $syntheticDiagnostic.LastTaskResult -or
        $syntheticDiagnostic.LastRunTime -ne '' -or
        $syntheticDiagnostic.NextRunTime -ne '' -or
        [int]$syntheticDiagnostic.NumberOfMissedRuns -ne 0) {
        throw 'Task Scheduler null timestamp self-test selhal.'
    }
    $missingInfoProperties = New-TaskDiagnosticRecord -TaskName 'Synthetic missing TaskInfo properties' -Task $syntheticTask -Info ([pscustomobject]@{})
    if ($missingInfoProperties.LastRunTime -ne '' -or $missingInfoProperties.NextRunTime -ne '') {
        throw 'Task Scheduler missing timestamp property self-test selhal.'
    }
    Write-Host '[PASS] Adapter self-test: null a chybejici Task Scheduler casy jsou zpracovany bez volani metody na $null.'
    $positiveRunHeaders = @(
        '--- old start: open-webui.exe serve --port 18080 ---',
        '--- 2026-08-12T18:30:40.0829076+02:00 start: C:\ProgramData\EInfra-OpenWebUI\venv\Scripts\open-webui.exe serve --host 127.0.0.1 --port 18080 ---',
        '--- 2026-08-12T18:30:40.0829076+02:00 start: "C:\Program Files\EInfra OpenWebUI\open-webui.exe" serve --host 127.0.0.1 --port 18080 ---'
    )
    foreach ($header in $positiveRunHeaders) {
        if (-not (Test-BackendRunStartLine -Line $header)) { throw ('Log start-header self-test nepoznal platnou hlavicku: {0}' -f $header) }
    }
    if (Test-BackendRunStartLine -Line '--- 2026 start: C:\temp\not-open-webui.exe serve --port 18080 ---') {
        throw 'Log start-header self-test prijal cizi executable.'
    }
    $lines = @($positiveRunHeaders[0],'ERROR function_study_tutor_old','--- new start: open-webui.exe serve --port 18080 ---','PermissionError unrelated')
    $latest = @(Select-LatestBackendRunLines -Lines $lines -MaximumLines 20)
    if ($latest.Count -ne 2 -or (Test-LatestLogIndicatesTutorStartupFailure -Lines $latest)) { throw 'Log segmentation self-test selhal pro posledni nesouvisejici beh.' }
    $failingLines = @('--- old start: open-webui.exe serve --port 18080 ---','PermissionError unrelated','--- new start: open-webui.exe serve --port 18080 ---','RuntimeError function_study_tutor_gateway_bootstrap')
    $latestFailure = @(Select-LatestBackendRunLines -Lines $failingLines -MaximumLines 20)
    if ($latestFailure.Count -ne 2 -or -not (Test-LatestLogIndicatesTutorStartupFailure -Lines $latestFailure)) { throw 'Log segmentation self-test nerozpoznal Tutor chybu v poslednim behu.' }
    Write-Host '[PASS] Adapter self-test: vlastnictvi procesu, ochrana Caddy/manageru a izolace posledniho behu logu.'

    $temporaryRoot = Join-Path ([IO.Path]::GetTempPath()) ('vut-einfra-adapter-selftest-' + [Guid]::NewGuid().ToString('N'))
    [IO.Directory]::CreateDirectory($temporaryRoot) | Out-Null
    try {
        $database = Join-Path $temporaryRoot 'webui.db'
        $initScript = Join-Path $temporaryRoot 'create-selftest-db.py'
        $verifyScript = Join-Path $temporaryRoot 'verify-selftest-db.py'
        $initSource = @'
import sqlite3
import sys

connection = sqlite3.connect(sys.argv[1])
try:
    connection.execute("create table function (id text primary key, is_active integer not null)")
    connection.executemany(
        "insert into function values (?,?)",
        [
            ("study_tutor_gateway_bootstrap", 1),
            ("study_tutor_pipe", 1),
            ("unrelated", 1),
        ],
    )
    connection.commit()
finally:
    connection.close()
'@
        $verifySource = @'
import sqlite3
import sys

connection = sqlite3.connect(sys.argv[1])
try:
    values = dict(connection.execute("select id,is_active from function"))
finally:
    connection.close()
expected = {
    "study_tutor_gateway_bootstrap": 0,
    "study_tutor_pipe": 0,
    "unrelated": 1,
}
raise SystemExit(0 if values == expected else 1)
'@
        $utf8NoBom = New-Object Text.UTF8Encoding($false)
        [IO.File]::WriteAllText($initScript,$initSource,$utf8NoBom)
        [IO.File]::WriteAllText($verifyScript,$verifySource,$utf8NoBom)
        $created = Invoke-CapturedProcess -FileName $Python -Arguments @($initScript,$database)
        if ($created.ExitCode -ne 0) { throw 'Nelze vytvorit self-test SQLite databazi.' }
        $fakeContext = [pscustomobject]@{ DatabasePath=$database; InstallRoot=$temporaryRoot }
        $audit = Invoke-OfflineTutorFunctionDeactivation -Context $fakeContext -Python $Python -RecoveryRoot (Join-Path $temporaryRoot 'backup')
        if (-not [bool]$audit.ok -or [int]$audit.updated_count -ne 2) { throw 'Offline Tutor recovery self-test nezmenil presne dve aktivni polozky.' }
        $verified = Invoke-CapturedProcess -FileName $Python -Arguments @($verifyScript,$database)
        if ($verified.ExitCode -ne 0) { throw 'Offline Tutor recovery self-test zmenil nesouvisejici Function nebo nezmenil Tutor Functions.' }
        Write-Host '[PASS] Adapter self-test: konzistentni SQLite zaloha a selektivni deaktivace pouze Tutor Functions.'
    }
    finally { Remove-Item -LiteralPath $temporaryRoot -Recurse -Force -ErrorAction SilentlyContinue }
}

function Start-EInfraBackendIfNeeded {
    param([Parameter(Mandatory=$true)]$Context, [Parameter(Mandatory=$true)][string]$Python)
    if (Test-BackendReady -BaseUrl $Context.InternalUrl) { return }
    [void](Test-TaskOwnership -TaskName $Context.BackendTaskName -RunnerPath $Context.RunnerPath -Component Backend)
    $task = Get-ScheduledTask -TaskName $Context.BackendTaskName -ErrorAction Stop
    try {
        if ([string]$task.State -eq 'Running') {
            if ($RestartPolicy -eq 'Never') { throw 'Backendova uloha bezi, ale /api/version neodpovida; RestartPolicy Never zakazuje opravu restartem.' }
            Restart-EInfraBackend -Context $Context
        }
        else {
            # Adapter 2.1.1 pouze znovu spustil task a mohl ponechat osireleho
            # potomka nebo stav Queued/Running. Pred kazdym startem proto provedeme
            # stejnou vlastnicky omezenou stop sekvenci jako puvodni serverovy
            # instalator: task -> spravovane procesy -> port -> klidovy stav tasku.
            Stop-EInfraBackendCompletely -Context $Context
            Write-Host ('[INFO] Spoustim planovanou ulohu {0} po uplnem uvolneni backendu.' -f $Context.BackendTaskName)
            Start-EInfraBackendTask -Context $Context
        }
        return
    }
    catch {
        $firstFailure = $_
        $latest = @(Get-LatestBackendLogExcerpt -Context $Context -MaximumLines $DiagnosticTailLines)
        $detected = Test-LatestLogIndicatesTutorStartupFailure -Lines $latest
        $recover = $TutorStartupRecovery -eq 'Required' -or ($TutorStartupRecovery -eq 'Auto' -and $detected)
        if (-not $recover) { throw $firstFailure }
        Write-Warning 'Start backendu selhal a posledni beh logu ukazuje na Tutor Function. Provedu zalohovanou offline deaktivaci pouze Tutor Functions a jeden cisty start.'
        Stop-EInfraBackendCompletely -Context $Context
        [void](Invoke-OfflineTutorFunctionDeactivation -Context $Context -Python $Python)
        Start-EInfraBackendTask -Context $Context
    }
}

function Get-TutorHealthClassification {
    param([Parameter(Mandatory=$true)]$Context)
    try {
        $response = Invoke-WebRequest -UseBasicParsing -Uri ($Context.InternalUrl.TrimEnd('/') + '/study-tutor/health') -Method Get -TimeoutSec 10
        $text = [string]$response.Content
        if ($text.TrimStart().StartsWith('<!doctype html',[StringComparison]::OrdinalIgnoreCase) -or $text.TrimStart().StartsWith('<html',[StringComparison]::OrdinalIgnoreCase)) {
            return [pscustomobject]@{ Current=$false; Classification='spa-fallback'; Detail='' }
        }
        $json = $text | ConvertFrom-Json
        $functionId = [string](Get-ObjectPropertyValue -Object $json -Names @('function_id') -DefaultValue '')
        $version = [string](Get-ObjectPropertyValue -Object $json -Names @('version') -DefaultValue '')
        $buildMarker = [string](Get-ObjectPropertyValue -Object $json -Names @('build_marker') -DefaultValue '')
        $current = $functionId -eq 'study_tutor_gateway_bootstrap' -and $version -eq $RuntimeVersion -and $buildMarker -like 'VUT-AI-TUTOR-1.26.5-*'
        return [pscustomobject]@{ Current=[bool]$current; Classification='json'; Detail=('version={0}; function={1}' -f $version,$functionId) }
    }
    catch { return [pscustomobject]@{ Current=$false; Classification='unavailable'; Detail=$_.Exception.Message } }
}

function Test-RestartUsefulAfterEngineFailure {
    param([Parameter(Mandatory=$true)]$Context, [Parameter(Mandatory=$true)][int]$ExitCode)
    if ($ExitCode -notin @(3,7)) { return $false }
    if (-not (Test-BackendReady -BaseUrl $Context.InternalUrl)) { return $true }
    $health = Get-TutorHealthClassification -Context $Context
    if ([bool]$health.Current) {
        Write-Warning ('Engine skoncil kodem {0}, ale backend i aktualni runtime odpovidaji ({1}); restart by tuto chybu neopravoval.' -f $ExitCode,$health.Detail)
        return $false
    }
    return $true
}

function Get-EngineArguments {
    param(
        [Parameter(Mandatory=$true)][string]$EngineAction,
        [Parameter(Mandatory=$true)][string]$PlatformName,
        [string]$BaseUrlValue,
        [Parameter(Mandatory=$true)][string]$ResolvedReport,
        [Parameter(Mandatory=$true)][string]$ResolvedPython,
        [string]$ResolvedToken,
        [string]$ResolvedPassword,
        [string]$ResolvedCa,
        [string]$CredentialEmail
    )
    $args = @('-NoLogo','-NoProfile','-NonInteractive','-ExecutionPolicy','Bypass','-File',$script:EnginePath,'-Action',$EngineAction,'-Platform',$PlatformName,'-PythonPath',$ResolvedPython,'-ReportPath',$ResolvedReport,'-RequestTimeout',[string]$RequestTimeout,'-StartupTimeout',[string]$StartupTimeout,'-RouteTimeout',[string]$RouteTimeout,'-RestartPolicy','Never')
    if (-not [string]::IsNullOrWhiteSpace($BaseUrlValue)) { $args += @('-BaseUrl',$BaseUrlValue) }
    if (-not [string]::IsNullOrWhiteSpace($ResolvedToken)) { $args += @('-TokenFile',$ResolvedToken) }
    if (-not [string]::IsNullOrWhiteSpace($CredentialEmail)) { $args += @('-Email',$CredentialEmail) }
    if (-not [string]::IsNullOrWhiteSpace($ResolvedPassword)) { $args += @('-PasswordFile',$ResolvedPassword) }
    if (-not [string]::IsNullOrWhiteSpace($ResolvedCa)) { $args += @('-CaCertificate',$ResolvedCa) }
    if ($InsecureTls) { $args += '-InsecureTls' }
    if ($NoRollback) { $args += '-NoRollback' }
    if ($KeepLegacyDisabled) { $args += '-KeepLegacyDisabled' }
    if (-not [string]::IsNullOrWhiteSpace($BackupDir)) { $args += @('-BackupDir',(Resolve-AbsolutePath -Path $BackupDir)) }
    if ($KeepPayloadDirectory) { $args += '-KeepPayloadDirectory' }
    if ($DiagnosticsEnabled) { $args += '-Debug' }
    return [string[]]$args
}

function Invoke-UniversalEngine {
    param(
        [Parameter(Mandatory=$true)][string]$EngineAction,
        [Parameter(Mandatory=$true)][string]$PlatformName,
        [string]$BaseUrlValue,
        [Parameter(Mandatory=$true)][string]$ResolvedReport,
        [Parameter(Mandatory=$true)][string]$ResolvedPython,
        [string]$ResolvedToken,
        [string]$ResolvedPassword,
        [string]$ResolvedCa,
        [hashtable]$Environment = @{},
        [string]$CredentialEmail
    )
    $arguments = Get-EngineArguments -EngineAction $EngineAction -PlatformName $PlatformName -BaseUrlValue $BaseUrlValue -ResolvedReport $ResolvedReport -ResolvedPython $ResolvedPython -ResolvedToken $ResolvedToken -ResolvedPassword $ResolvedPassword -ResolvedCa $ResolvedCa -CredentialEmail $CredentialEmail
    return Invoke-CapturedProcess -FileName 'powershell.exe' -Arguments $arguments -Environment $Environment
}

function Get-PublicReportPath {
    param([Parameter(Mandatory=$true)][string]$ResolvedReport)
    $directory = [IO.Path]::GetDirectoryName($ResolvedReport)
    $name = [IO.Path]::GetFileNameWithoutExtension($ResolvedReport)
    $extension = [IO.Path]::GetExtension($ResolvedReport)
    if ([string]::IsNullOrWhiteSpace($extension)) { $extension = '.json' }
    return Join-Path $directory ($name + '-public' + $extension)
}

$EmbeddedEnginePayload = ''
$ExpectedEngineSha256 = 'f8f3d28981da8cf2866bd71d4551291a589c290ebd5ef35f764601cacb092937'
$script:EmbeddedEngineDirectory = Join-Path ([IO.Path]::GetTempPath()) ('vut-tutor-einfra-engine-2.1.8-' + [Guid]::NewGuid().ToString('N'))
[IO.Directory]::CreateDirectory($script:EmbeddedEngineDirectory) | Out-Null
$script:EnginePath = Join-Path $script:EmbeddedEngineDirectory 'install-vut-ai-tutor-universal-v2.0.2.ps1'
$compressedEngine = [Convert]::FromBase64String($EmbeddedEnginePayload)
$engineInput = New-Object IO.MemoryStream(,$compressedEngine)
try {
    $engineGzip = New-Object IO.Compression.GZipStream($engineInput,[IO.Compression.CompressionMode]::Decompress)
    try {
        $engineOutput = [IO.File]::Create($script:EnginePath)
        try { $engineGzip.CopyTo($engineOutput) } finally { $engineOutput.Dispose() }
    } finally { $engineGzip.Dispose() }
} finally { $engineInput.Dispose() }
$actualEngineSha = (Get-FileHash -LiteralPath $script:EnginePath -Algorithm SHA256).Hash.ToLowerInvariant()
if ($actualEngineSha -ne $ExpectedEngineSha256) {
    throw ('Vlozeny univerzalni engine ma chybny SHA-256: ocekavano {0}, ziskano {1}' -f $ExpectedEngineSha256,$actualEngineSha)
}
$python = Resolve-Python -Requested $PythonPath
$resolvedReport = Resolve-AbsolutePath -Path $ReportPath
$script:ResolvedReportPath = $resolvedReport
$resolvedToken = Resolve-AbsolutePath -Path $TokenFile -MustExist
$resolvedPassword = Resolve-AbsolutePath -Path $PasswordFile -MustExist
$resolvedCa = Resolve-AbsolutePath -Path $CaCertificate -MustExist
$environment = @{}
$credentialEmail = $Email
if ($PromptForCredential) {
    $credential = Get-Credential -Message 'Open WebUI administrator credentials'
    $credentialEmail = $credential.UserName
    $environment['VUT_INSTALL_EMAIL'] = $credential.UserName
    $environment['VUT_INSTALL_PASSWORD'] = $credential.GetNetworkCredential().Password
}

Write-Host ('[INFO] VUT AI Tutor e-INFRA Windows adapter {0}; runtime {1}.' -f $AdapterVersion,$RuntimeVersion)
Write-Host ('[INFO] Universal engine: {0}' -f $script:EnginePath)
Write-Host ('[INFO] Python: {0}' -f $python)

if ($Action -eq 'SelfTest') {
    Invoke-AdapterSelfTest -Python $python
    $result = Invoke-UniversalEngine -EngineAction SelfTest -PlatformName BareMetal -ResolvedReport $resolvedReport -ResolvedPython $python -ResolvedToken $resolvedToken -ResolvedPassword $resolvedPassword -ResolvedCa $resolvedCa -Environment $environment -CredentialEmail $credentialEmail
    if ($result.ExitCode -ne 0) { exit $result.ExitCode }
    Write-Host '[PASS] Self-test kompletni e-INFRA sady prosel.'
    exit 0
}

Assert-WindowsAdministrator
$context = Get-EInfraRuntimeContext
Write-Host ('[INFO] Runtime config: {0}' -f $context.RuntimeConfigPath)
Write-Host ('[INFO] Interni Open WebUI API: {0}' -f $context.InternalUrl)
if (-not [string]::IsNullOrWhiteSpace($context.PublicUrl)) { Write-Host ('[INFO] Verejna URL pres Caddy: {0}' -f $context.PublicUrl) }

[void](Test-TaskOwnership -TaskName $context.BackendTaskName -RunnerPath $context.RunnerPath -Component Backend)
[void](Test-TaskOwnership -TaskName $context.ProxyTaskName -RunnerPath $context.RunnerPath -Component Caddy)

if ($Action -eq 'BackendRecovery') {
    Start-EInfraBackendIfNeeded -Context $context -Python $python
    Write-Host ('[PASS] Backend e-INFRA Open WebUI je znovu dostupny na {0}.' -f $context.InternalUrl)
    exit 0
}
if ($Action -in @('Install','Repair')) { Start-EInfraBackendIfNeeded -Context $context -Python $python }
elseif (-not (Test-BackendReady -BaseUrl $context.InternalUrl)) {
    throw ('Interni Open WebUI backend neodpovida: {0}' -f $context.InternalUrl)
}

$result = Invoke-UniversalEngine -EngineAction $Action -PlatformName BareMetal -BaseUrlValue $context.InternalUrl -ResolvedReport $resolvedReport -ResolvedPython $python -ResolvedToken $resolvedToken -ResolvedPassword $resolvedPassword -ResolvedCa $resolvedCa -Environment $environment -CredentialEmail $credentialEmail

if ($result.ExitCode -ne 0 -and $Action -in @('Install','Repair') -and $RestartPolicy -eq 'OnFailure' -and (Test-RestartUsefulAfterEngineFailure -Context $context -ExitCode ([int]$result.ExitCode))) {
    Write-Warning ('Prvni pokus skoncil kodem {0} a diagnostika potvrzuje, ze restart muze obnovit backend nebo nacist novy runtime; provedu jeden vlastnicky overeny restart.' -f $result.ExitCode)
    Restart-EInfraBackend -Context $context
    $result = Invoke-UniversalEngine -EngineAction Repair -PlatformName BareMetal -BaseUrlValue $context.InternalUrl -ResolvedReport $resolvedReport -ResolvedPython $python -ResolvedToken $resolvedToken -ResolvedPassword $resolvedPassword -ResolvedCa $resolvedCa -Environment $environment -CredentialEmail $credentialEmail
}

if ($result.ExitCode -ne 0) { exit $result.ExitCode }

if ($Action -in @('Install','Repair') -and $RestartPolicy -eq 'Always') {
    Restart-EInfraBackend -Context $context
    $verifyAfterRestart = Invoke-UniversalEngine -EngineAction Verify -PlatformName BareMetal -BaseUrlValue $context.InternalUrl -ResolvedReport $resolvedReport -ResolvedPython $python -ResolvedToken $resolvedToken -ResolvedPassword $resolvedPassword -ResolvedCa $resolvedCa -Environment $environment -CredentialEmail $credentialEmail
    if ($verifyAfterRestart.ExitCode -ne 0) { exit $verifyAfterRestart.ExitCode }
}

if ($Action -in @('Install','Repair','Verify','Preflight') -and $PublicVerification -ne 'Skip' -and -not [string]::IsNullOrWhiteSpace($context.PublicUrl)) {
    $publicReport = Get-PublicReportPath -ResolvedReport $resolvedReport
    $publicAction = if ($Action -eq 'Preflight') { 'Preflight' } else { 'Verify' }
    Write-Host ('[INFO] Overuji Caddy/HTTPS pres verejnou URL; report: {0}' -f $publicReport)
    $publicResult = Invoke-UniversalEngine -EngineAction $publicAction -PlatformName Remote -BaseUrlValue $context.PublicUrl -ResolvedReport $publicReport -ResolvedPython $python -ResolvedToken $resolvedToken -ResolvedPassword $resolvedPassword -ResolvedCa $resolvedCa -Environment $environment -CredentialEmail $credentialEmail
    if ($publicResult.ExitCode -ne 0) {
        if ($PublicVerification -eq 'Required') { exit $publicResult.ExitCode }
        Write-Warning ('Interni instalace prosla, ale verejna kontrola pres Caddy skoncila kodem {0}. Overte DNS hairpin nebo spustte verifier z jineho klienta.' -f $publicResult.ExitCode)
    }
}

Write-Host ('[PASS] Operace {0} pro e-INFRA Windows server byla dokoncena. Report: {1}' -f $Action,$resolvedReport)
if ($KeepPayloadDirectory) { Write-Host ('[INFO] Vlozeny engine ponechan v: {0}' -f $script:EmbeddedEngineDirectory) } else { Remove-Item -LiteralPath $script:EmbeddedEngineDirectory -Recurse -Force -ErrorAction SilentlyContinue }
